INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 2, 91002, 10118, 2834, 40, "青空の下で謁見", 5118061, "ペコリーヌとの出会い", 20063115, "フリーマーケット会場", 1, 7);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 2, 91002, 10118, 2835, 40, "未来の騎空団\nマスコット？", 5118062, "マホとの出会い", 20063115, "フリーマーケット会場", 1, 7);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 2, 91002, 10118, 2837, 40, "お嬢さまからの\n緊急依頼", 5118063, "アキノとの出会い", 20063115, "ランドソル市街地", 1, 7);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 2, 91002, 10118, 4108402, 40, "黄金色の悩みごと", 5118064, "ジュンとの出会い", 20063115, "フリーマーケット会場", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 2, 91002, 10118, 4107402, 40, "白熱！　格闘大会！", 5118065, "カオリとの出会い", 20063115, "フリーマーケット会場", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (1, 8, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 2, 91002, 10118, 9000227, 40, "祭り太鼓はオーエドの華", 5118066, "ニノンとの出会い", 20063115, "オーエド町", 1, 16);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 3, 91002, 10118, 2101181, 40, "人気者は遅れて\nやってくる", 5118067, "スズナとの出会い", 20063115, "フリーマーケット会場", 1, 19);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 3, 91002, 10118, 4109402, 40, "巫女・ミーツ・魔法少女", 5118068, "ナナカとの出会い", 20063115, "ランドソル市街地", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 3, 91002, 10118, 4305402, 40, "ネズ耳は二度なくなる", 5118069, "キャル＆コッコロとの出会い", 20063115, "フリーマーケット会場", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 3, 91002, 10118, 4101402, 40, "この出会いにカンパイ！", 5118070, "ユカリとの出会い", 20063115, "ランドソル市街地", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 8, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 3, 91002, 10118, 4106402, 40, "陰陽アンサンブル", 5118071, "アオイとの出会い", 20063115, "ランドソル市街地", 1, 18);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (1, 8, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 3, 91002, 10118, 2836, 40, "運試し十番勝負！", 5118072, "シノブとの出会い", 20063115, "フリーマーケット会場", 1, 7);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (0, 0, 0, 1, 0, 10118, 0, 0, "彼女たちの新たな日常", 5118600, "オープニング", 20063115, 0, 0, 0);
